INSERT INTO mammoth_fact (category, title, description) VALUES ('Anatomy', 'Curved Tusks', 'Woolly mammoth tusks could grow up to 4.2 meters (14 feet) long and were curved in a distinctive spiral shape. They were used for foraging, fighting, and clearing snow to reach vegetation beneath.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Anatomy', 'Woolly Coat', 'The woolly mammoth had a thick double-layered coat consisting of coarse outer guard hairs up to 90 cm long and a dense, fine undercoat for insulation against extreme cold.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Anatomy', 'Massive Size', 'Adult woolly mammoths stood about 3 to 3.4 meters (10 to 11 feet) tall at the shoulder and weighed between 4 and 6 metric tons, roughly the same size as modern African elephants.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Anatomy', 'Small Ears and Tail', 'Compared to modern elephants, mammoths had significantly smaller ears and shorter tails to minimize heat loss in frigid environments, a classic adaptation to cold climates.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Anatomy', 'Fatty Hump', 'Woolly mammoths had a large hump of fat behind their skull on the upper back, similar to a camel. This fat reserve provided energy during harsh winters when food was scarce.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Habitat', 'Ice Age Roamers', 'Mammoths thrived during the Pleistocene epoch, roaming across vast stretches of North America, Europe, Asia, and even parts of Africa over a span of roughly 5 million years.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Habitat', 'Mammoth Steppe', 'The woolly mammoth inhabited the mammoth steppe, a vast cold grassland ecosystem that stretched from Spain to Canada and was the most extensive biome on Earth during the last Ice Age.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Habitat', 'Island Dwellers', 'Some mammoth populations survived on isolated islands long after mainland extinction. Dwarf mammoths lived on Wrangel Island in the Arctic Ocean until about 4,000 years ago.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Diet', 'Herbivorous Giants', 'Mammoths were herbivores that consumed an estimated 180 kilograms (400 pounds) of vegetation daily, including grasses, sedges, shrubs, and tree bark.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Diet', 'Specialized Teeth', 'Mammoth molars had flat, ridged surfaces ideal for grinding tough grasses. They went through six sets of teeth in their lifetime, with new molars pushing out worn ones from behind.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Diet', 'Preserved Stomach Contents', 'Scientists have found preserved stomach contents in frozen mammoth carcasses, revealing meals of buttercups, dandelions, mosses, and various grasses eaten shortly before death.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Extinction', 'End of an Era', 'Most mammoth species went extinct approximately 10,000 years ago at the end of the last Ice Age. Climate change and human hunting are considered the primary drivers of their extinction.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Extinction', 'Last Survivors', 'The last known population of woolly mammoths survived on Wrangel Island until approximately 2000 BCE, meaning they were alive when the Egyptian pyramids were being built.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Extinction', 'Genetic Decline', 'DNA studies of the Wrangel Island mammoths show they suffered from severe inbreeding and accumulated harmful mutations, likely contributing to their final extinction.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Discovery', 'Frozen Specimens', 'Remarkably well-preserved mammoth remains have been found frozen in the permafrost of Siberia, some with intact soft tissue, hair, and even liquid blood still present.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Discovery', 'Baby Lyuba', 'In 2007, a reindeer herder in Siberia discovered a 42,000-year-old baby mammoth named Lyuba. She is the most perfectly preserved mammoth specimen ever found, with skin, organs, and even her last meal intact.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Discovery', 'Cave Art', 'Ancient humans depicted mammoths in cave paintings across Europe, most notably in the caves of Rouffignac in France, providing valuable insights into mammoth appearance and human-mammoth interactions.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Discovery', 'Mammoth Bone Dwellings', 'Prehistoric humans in Ukraine and Russia built shelters from mammoth bones. Excavated sites reveal huts constructed from hundreds of bones arranged in circular patterns, dating back 15,000 to 20,000 years.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Species', 'Woolly Mammoth', 'The woolly mammoth (Mammuthus primigenius) is the most well-known species. It evolved about 400,000 years ago in East Asia and spread across the northern hemisphere.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Species', 'Columbian Mammoth', 'The Columbian mammoth (Mammuthus columbi) inhabited North America and was larger than the woolly mammoth, standing up to 4 meters tall. It had less hair and preferred warmer grasslands.');
INSERT INTO mammoth_fact (category, title, description) VALUES ('Species', 'Steppe Mammoth', 'The steppe mammoth (Mammuthus trogontherii) was one of the largest mammoth species, reaching heights of 4.5 meters (15 feet). It roamed the grasslands of Europe and Asia during the Middle Pleistocene.');
